// t1_logic
//
// The logic for the T1 function.
// CSA tree reduces 5 operands to 2 before final carry-propagate.
//----------------------------------------------------------------
always @*
  begin : t1_logic
    reg [31 : 0] sum1;
    reg [31 : 0] ch;
    reg [31 : 0] csa1_s;
    reg [31 : 0] csa1_c;
    reg [31 : 0] csa2_s;
    reg [31 : 0] csa2_c;
    reg [31 : 0] csa3_s;
    reg [31 : 0] csa3_c;

    sum1 = {e_reg[5  : 0], e_reg[31 :  6]} ^
           {e_reg[10 : 0], e_reg[31 : 11]} ^
           {e_reg[24 : 0], e_reg[31 : 25]};

    ch = (e_reg & f_reg) ^ ((~e_reg) & g_reg);

    // CSA stage 1: reduce h_reg, sum1, ch -> (csa1_s, csa1_c)
    csa1_s = h_reg ^ sum1 ^ ch;
    csa1_c = {((h_reg & sum1) | (h_reg & ch) | (sum1 & ch))[30:0], 1'b0};

    // CSA stage 2: reduce csa1_s, csa1_c, w_data -> (csa2_s, csa2_c)
    csa2_s = csa1_s ^ csa1_c ^ w_data;
    csa2_c = {((csa1_s & csa1_c) | (csa1_s & w_data) | (csa1_c & w_data))[30:0], 1'b0};

    // CSA stage 3: reduce csa2_s, csa2_c, k_data -> (csa3_s, csa3_c)
    csa3_s = csa2_s ^ csa2_c ^ k_data;
    csa3_c = {((csa2_s & csa2_c) | (csa2_s & k_data) | (csa2_c & k_data))[30:0], 1'b0};

    // Final carry-propagate add of two operands
    t1 = csa3_s + csa3_c;
  end // t1_logic

