//----------------------------------------------------------------
always @*
  begin : t1_logic
    reg [31 : 0] sum1;
    reg [31 : 0] ch;
    reg [31 : 0] csa1_s, csa1_c;
    reg [31 : 0] csa2_s, csa2_c;
    reg [31 : 0] csa3_s, csa3_c;

    sum1 = {e_reg[5  : 0], e_reg[31 :  6]} ^
