    // CSA stage 1a: (h_reg, sum1, ch) -> (csa1_s, csa1_c)
    csa1_s = h_reg ^ sum1 ^ ch;
    csa1_c = ((h_reg & sum1) | (h_reg & ch) | (sum1 & ch)) << 1;

    // CSA stage 1b: (w_data, k_data, csa1_s) -> (csa2_s, csa2_c)
    csa2_s = w_data ^ k_data ^ csa1_s;
    csa2_c = ((w_data & k_data) | (w_data & csa1_s) | (k_data & csa1_s)) << 1;

    // CSA stage 2: (csa1_c, csa2_s, csa2_c) -> (csa3_s, csa3_c)
    csa3_s = csa1_c ^ csa2_s ^ csa2_c;
    csa3_c = ((csa1_c & csa2_s) | (csa1_c & csa2_c) | (csa2_s & csa2_c)) << 1;

    // Final carry-propagate add: two operands only
    t1 = csa3_s + csa3_c;
  end // t1_logic

